import { useMemo } from "react";
import { propsToDataAttrs } from "@/registry/nextjs/lib/utilities";
import "@/registry/nextjs/components/column/column.css";

interface LkColumnProps extends React.HTMLAttributes<HTMLDivElement> {
  alignItems?: "start" | "center" | "end" | "stretch";
  justifyContent?: "start" | "center" | "end" | "space-between" | "space-around";
  gap?: LkSizeUnit | "none";
  wrapChildren?: boolean;
  defaultChildBehavior?: "auto-grow" | "auto-shrink" | "ignoreFlexRules" | "ignoreIntrinsicSize";
  children?: React.ReactNode;
}

export default function Column(props: LkColumnProps) {
  const { children, alignItems="stretch", justifyContent="start", gap, wrapChildren, defaultChildBehavior, ...restProps } = props;

  const lkColumnAttrs = useMemo(
    () => propsToDataAttrs({ alignItems, justifyContent, gap, wrapChildren, defaultChildBehavior }, "column"),
    [alignItems, justifyContent, gap, wrapChildren, defaultChildBehavior]
  );

  return (
    <div {...lkColumnAttrs} {...restProps} data-lk-component="column">
      {children}
    </div>
  );
}

[data-lk-component="column"] {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 0;
  flex-wrap: nowrap;
}

/* align-items variations */
[data-lk-column-align-items="start"] {
  align-items: flex-start;
}

[data-lk-column-align-items="center"] {
  align-items: center;
}

[data-lk-column-align-items="end"] {
  align-items: flex-end;
}

[data-lk-column-align-items="stretch"] {
  align-items: stretch;
}

/* justify-content variations */
[data-lk-column-justify-content="start"] {
  justify-content: flex-start;
}

[data-lk-column-justify-content="center"] {
  justify-content: center;
}

[data-lk-column-justify-content="end"] {
  justify-content: flex-end;
}

[data-lk-column-justify-content="space-between"] {
  justify-content: space-between;
}

[data-lk-column-justify-content="space-around"] {
  justify-content: space-around;
}

/* Gap */
[data-lk-column-gap="3xs"] {
  gap: var(--lk-size-3xs);
}

[data-lk-column-gap="2xs"] {
  gap: var(--lk-size-2xs);
}

[data-lk-column-gap="xs"] {
  gap: var(--lk-size-xs);
}

[data-lk-column-gap="sm"] {
  gap: var(--lk-size-sm);
}

[data-lk-column-gap="md"] {
  gap: var(--lk-size-md);
}

[data-lk-column-gap="lg"] {
  gap: var(--lk-size-lg);
}

[data-lk-column-gap="xl"] {
  gap: var(--lk-size-xl);
}

[data-lk-column-gap="2xl"] {
  gap: var(--lk-size-2xl);
}

[data-lk-column-gap="3xl"] {
  gap: var(--lk-size-3xl);
}

[data-lk-column-gap="4xl"] {
  gap: var(--lk-size-4xl);
}
